// HT-MVP-OWNER-UAT-P0-RECOVERY-01 — immutable build-time public feed.
// Must be generated by an authorized build; never writes staging, production,
// repository refs, publishing providers, or any credential-bearing file.
// Metadata-only unless HT_P0_EDITORIAL_CLASSIFICATION_FILE names an editorial
// classification; bodies are not even downloaded without one.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { buildPublicManifest } from "./public-manifest.mjs";
import { probePublicPublisher } from "./public-source-readonly-probe.mjs";

const output="apps/mobile/public/healthtimes-public-feed.json";
const classificationPath=process.env.HT_P0_EDITORIAL_CLASSIFICATION_FILE;
const classification=classificationPath ? JSON.parse(await readFile(classificationPath,"utf8")) : null;
const result=await probePublicPublisher({ includeBody:Boolean(classification) });
if(result.status!=="PROBE_SUCCEEDED_NOT_AUTHORIZED_AS_FEED" || !result.latestWithin7Days || !result.latestTwentyMetadata?.length){
  console.error("P0 verified metadata unavailable. Refusing to generate fresh-looking feed.");
  process.exit(2);
}
const manifest=buildPublicManifest({probe:result,classification,generatedAt:new Date().toISOString()});
await mkdir(dirname(output),{recursive:true});
await writeFile(output,JSON.stringify(manifest,null,2)+"\n",{mode:0o644});
console.log(JSON.stringify({
  source:manifest.source,output,verifiedAt:manifest.verifiedAt,latest:manifest.publicationDateAtLatest,
  records:manifest.count,hash:manifest.contentHashSha256,
  fullArticleBodies:manifest.contentBodyAvailable,
  editorialClassificationSupplied:Boolean(classification),
  reader15MinuteSla:false,authorization:"NOT_DEPLOYED"
},null,2));
